// Generated by scripts/generate-file-types.py; edit resources/file-types.json.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FileIconKind {
    Pdf,
    Document,
    Text,
    Spreadsheet,
    Presentation,
    Image,
    Audio,
    Video,
    Archive,
    Package,
    Book,
    Font,
    Config,
    Code,
}
pub fn kind(name: &str) -> Option<FileIconKind> {
    let name = name
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(name)
        .to_ascii_lowercase();
    if name == "readme"
        || name == "license"
        || name == "licence"
        || name == "changelog"
        || name == "authors"
    {
        return Some(FileIconKind::Text);
    }
    if name == ".env"
        || name == ".gitignore"
        || name == ".gitattributes"
        || name == ".gitmodules"
        || name == ".editorconfig"
        || name == ".npmrc"
        || name == ".nvmrc"
        || name == ".prettierrc"
        || name == ".eslintrc"
        || name == ".bashrc"
        || name == ".zshrc"
        || name == ".bash_profile"
        || name == ".zprofile"
        || name == ".profile"
        || name.starts_with(".env.")
    {
        return Some(FileIconKind::Config);
    }
    if name == "dockerfile"
        || name == "makefile"
        || name == "cmakelists.txt"
        || name == "gemfile"
        || name == "rakefile"
        || name == "procfile"
        || name == "justfile"
    {
        return Some(FileIconKind::Code);
    }
    let extension = name
        .rsplit_once('.')
        .filter(|(stem, ext)| !stem.is_empty() && !ext.is_empty())
        .map(|(_, ext)| ext)?;
    match extension {
        "pdf" => Some(FileIconKind::Pdf),
        "doc" | "docx" | "odt" | "rtf" | "pages" => Some(FileIconKind::Document),
        "txt" | "md" | "markdown" | "log" | "rst" | "tex" => Some(FileIconKind::Text),
        "xls" | "xlsx" | "ods" | "csv" | "tsv" | "numbers" => Some(FileIconKind::Spreadsheet),
        "ppt" | "pptx" | "odp" | "key" => Some(FileIconKind::Presentation),
        "icns" | "psd" | "raw" | "jpg" | "jpeg" | "png" | "gif" | "webp" | "heic" | "heif"
        | "avif" | "bmp" | "tif" | "tiff" | "svg" | "ico" => Some(FileIconKind::Image),
        "mp3" | "m4a" | "aac" | "wav" | "flac" | "ogg" | "opus" | "aiff" | "aif" | "wma" => {
            Some(FileIconKind::Audio)
        }
        "mp4" | "mov" | "mkv" | "avi" | "webm" | "m4v" | "wmv" | "mpeg" | "mpg" => {
            Some(FileIconKind::Video)
        }
        "zip" | "7z" | "rar" | "tar" | "gz" | "bz2" | "xz" | "tgz" | "zst" | "lz" | "lzma"
        | "tbz2" => Some(FileIconKind::Archive),
        "dmg" | "iso" | "pkg" | "exe" | "dll" | "dylib" | "so" => Some(FileIconKind::Package),
        "epub" | "mobi" | "azw" | "azw3" => Some(FileIconKind::Book),
        "ttf" | "otf" | "woff" | "woff2" => Some(FileIconKind::Font),
        "json" | "yaml" | "yml" | "toml" | "xml" | "ini" | "conf" | "cfg" | "properties"
        | "lock" => Some(FileIconKind::Config),
        "dart" | "swift" | "rs" | "java" | "kt" | "kts" | "js" | "jsx" | "ts" | "tsx" | "py"
        | "go" | "c" | "h" | "cpp" | "hpp" | "cc" | "cxx" | "hxx" | "cs" | "sh" | "bash"
        | "zsh" | "ps1" | "rb" | "php" | "lua" | "sql" | "html" | "htm" | "css" | "scss"
        | "sass" | "less" | "vue" | "svelte" | "ipynb" | "clj" | "cljs" | "pm" | "groovy"
        | "gradle" | "cmake" | "r" | "m" | "mm" | "ex" | "exs" | "erl" | "hs" | "scala" | "sc"
        | "pl" | "bat" | "cmd" | "fish" => Some(FileIconKind::Code),
        _ => None,
    }
}
